-- Ejecutar en el SQL Editor de Supabase. Toda lectura/escritura exige usuario autenticado.
create extension if not exists "uuid-ossp";
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, created_at timestamptz default now());
create table public.owners (id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, dni text, phone text, whatsapp text, email text, address text, city text, notes text, created_at timestamptz default now());
create table public.pets (id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade, owner_id uuid references public.owners(id) on delete set null, name text not null, species text not null, breed text, sex text, birth_date date, weight numeric, color text, microchip text, photo_path text, status text default 'Activo', notes text, created_at timestamptz default now());
create table public.vaccine_catalog (id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, created_at timestamptz default now());
create table public.medical_records (id uuid primary key default uuid_generate_v4(), pet_id uuid not null references public.pets(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, visit_date date not null, reason text not null, anamnesis text, physical_exam text, weight numeric, temperature numeric, diagnosis text, treatment text, medication text, instructions text, notes text, veterinarian text, created_at timestamptz default now());
create table public.vaccinations (id uuid primary key default uuid_generate_v4(), pet_id uuid not null references public.pets(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, vaccine_name text not null, applied_date date, next_dose_date date, dose_number integer, lot text, manufacturer text, veterinarian text, notes text, created_at timestamptz default now());
create table public.reminders (id uuid primary key default uuid_generate_v4(), vaccination_id uuid not null references public.vaccinations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, scheduled_for date not null, status text default 'Pendiente', created_at timestamptz default now());
create table public.whatsapp_logs (id uuid primary key default uuid_generate_v4(), reminder_id uuid references public.reminders(id) on delete set null, user_id uuid not null references auth.users(id) on delete cascade, message text, method text, status text not null default 'Pendiente', error text, sent_at timestamptz, created_at timestamptz default now());
create index pets_owner_idx on public.pets(owner_id); create index pets_microchip_idx on public.pets(microchip); create index vacc_next_idx on public.vaccinations(next_dose_date); create index records_pet_idx on public.medical_records(pet_id);
alter table public.profiles enable row level security; alter table public.owners enable row level security; alter table public.pets enable row level security; alter table public.vaccine_catalog enable row level security; alter table public.medical_records enable row level security; alter table public.vaccinations enable row level security; alter table public.reminders enable row level security; alter table public.whatsapp_logs enable row level security;
create policy "own profiles" on public.profiles for all using (auth.uid()=id) with check(auth.uid()=id);
create policy "own owners" on public.owners for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own pets" on public.pets for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own catalog" on public.vaccine_catalog for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own records" on public.medical_records for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own vaccinations" on public.vaccinations for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own reminders" on public.reminders for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own logs" on public.whatsapp_logs for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
